import {graphTasks,graphCorrect,catalystTasks,catalystCorrect} from './kinetic-models.js?v=20261023-physicscomplete01';
import {showKinetics} from './kinetic-scenes.js?v=20261023-physicscomplete01';
export function mountKineticsWidget(l,p,root,{save,done,feedback}){const graphs=l.widget==='kinetics-graphs',tasks=graphs?graphTasks:catalystTasks,w=p.widget;w.task??=0;w.answers??={};w.passed??=[];const i=w.task%tasks.length,t=tasks[i],a=w.answers[t.id]??={};w.answers[t.id]=a;const $=s=>root.querySelector(s),valid=()=>graphs?graphCorrect(t,a):catalystCorrect(t,a);const sel=(id,label,opts)=>`<label class="field-label" for="kinetic-${id}">${label}</label><select class="lab-select" id="kinetic-${id}"><option value="">Choose…</option>${opts.map(([v,s])=>`<option value="${v}">${s}</option>`).join('')}</select>`;let body=`<p><b>${i+1} / 3 · ${t.title}</b></p><p>${t.prompt}</p>`,keys=[];
if(!graphs){body+=t.fields.map(([id,label,opts])=>sel(id,label,opts)).join('');keys=t.fields.map(f=>f[0]);}else if(t.id==='plot'){keys=['p20','p40','p60'];body+=keys.map((id,j)=>`<label class="field-label" for="kinetic-${id}">Volume at${20+j*20} s / cm³</label><input class="lab-input" id="kinetic-${id}" type="number" step="any">`).join('');}else if(t.id==='compare'){body+=sel('fast','Greater initial rate',[['A','Curve A'],['B','Curve B'],['same','Same rate']])+sel('final','Final product amount',[['A','Greater in A'],['B','Greater in B'],['same','Same amount']]);keys=['fast','final'];}else{a.tilt??='0';body+='<label class="field-label" for="kinetic-tilt">Tangent tilt · flat to steep</label><input class="lab-input" id="kinetic-tilt" type="range" min="0" max="8" step="1">'+sel('rate','Rate at30 s compared with plateau',[['greater','Greater'],['same','Same'],['lower','Lower']]);keys=['tilt','rate'];}
root.innerHTML=body+'<button class="secondary" id="checkKinetic">Check reasoning</button><button class="secondary" id="nextKinetic">Next task →</button><p id="kineticProgress">'+w.passed.length+' / 3 correct</p>';const draw=()=>showKinetics(graphs?t.id:'catalyst',t,a,w.passed.includes(t.id)&&valid());for(const k of keys){const el=$('#kinetic-'+k);el.value=a[k]??'';el[el.tagName==='INPUT'?'oninput':'onchange']=e=>{a[k]=e.target.value;save();draw();};}draw();$('#checkKinetic').onclick=()=>{if(!valid()){feedback(graphs?(t.id==='plot'?'Use the table reading at each specified time. Check the vertical coordinate, not the time value.':t.id==='compare'?'Compare the early steepness separately from the final plateau.':'Pivot the line to match the curve locally, rather than joining endpoints. At the plateau the measured rate is zero.'):'A catalyst lowers the pathway barrier without changing endpoints or being used up overall. Use the rate/recovery evidence and distinguish speed from final amount.',true);return;}if(!w.passed.includes(t.id))w.passed.push(t.id);save();draw();$('#kineticProgress').textContent=w.passed.length+' / 3 correct';feedback('Correct: the representation and your reasoning agree.');if(w.passed.length===3){p.widgetDone=true;save();done();}};$('#nextKinetic').onclick=()=>{w.task=(i+1)%3;save();feedback('');mountKineticsWidget(l,p,root,{save,done,feedback});};}
